void swap_ints(int a, int b) {
    // Make the caller's variables actually change.
}

tests:
int x = 1, y = 2;
swap_ints(x, y);
CHECK_EQ(x, 2);
CHECK_EQ(y, 1);

int same = 7;
swap_ints(same, same);
CHECK_EQ(same, 7);

solution:
void swap_ints(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}
